//! La feuille de route : ce qui est fait, ce qui vient.
//!
//! Des données, pas du balisage : `crate::doc` est le seul rendu, et une
//! traduction manquante ne compile pas.

use crate::doc::{Block, DlItem, Doc, Tone};

pub static ROADMAP_EN: Doc = Doc {
    title: "Roadmap",
    lede: "Where each part stands, what comes next in the order it matters and what is in its way — and what is deliberately not planned.",
    blocks: &[
        Block::P("Nothing here has a date. The order reflects what would make wisq better for someone using it today, not what is most interesting to build."),
        Block::P("This page is a summary of docs/ROADMAP.md, the project's working record. That file is written in French as the work happens, one slice at a time, and each slice says what it measured, what it broke on purpose to see whether a test noticed, and what it does not show. CHANGELOG.md lists what each release carried; docs/JOURNAL.md, beside the roadmap, records the sessions and what was decided in them. The details, the dates and the command behind each figure live there."),
        Block::H2("Where each part stands"),
        Block::P("One row per area, in the words the roadmap and the README's status table use: what is done, and the first thing named next — or nothing, when nothing is."),
        Block::Table { columns: &["Area", "Done", "Next"], rows: &[&["Remote — VNC", "An RFB 3.8 client: the classic encodings, then zlib, ZRLE and Tight with JPEG over compression streams that live as long as the session; continuous updates, the server's cursor drawn locally, desktop resize, the clipboard, and reconnection with exponential backoff that never retries a refused password.", "Nothing named for VNC itself. Three things that concern remote connections in general sit on the roadmap's list of what waits for an Apple machine — see below."], &["Remote — SPICE", "Complete: every channel on its own connection, the codecs SPICE invented for itself, sound both ways, the clipboard, video streams, the three caches, `.vv` files, and a file sent from the phone into the guest.", "Nothing named. The video codecs a server could pick are left unannounced on purpose, because wisq does not decode them."], &["Remote — RDP", "Negotiation, MCS, key exchange, licensing, capabilities, RLE bitmaps and input, measured against a real xrdp with FreeRDP as the oracle for pixels; `.rdp` files are read.", "NLA/CredSSP first, because modern Windows asks for it by default; then TLS, the virtual channels, the cursor, resizing mid-session, RemoteFX and H.264."], &["Local — RISC-V", "rv32ima written twice, in Rust and in Swift, and compared instruction by instruction in CI — the Rust one ships. A real kernel to a shell, a terminal that keeps an editor alive, suspension as a snapshot, a disk, memory you size.", "Nothing scheduled. Full distributions went to the x86-64 machine when the local platform changed."], &["Local — x86-64", "A stock Alpine kernel to the initramfs rescue shell, where QEMU lands on the same images. A disk, a snapshot, up to 16 GiB of memory within what the phone allows, and installation images started from what is inside them.", "A distribution started from its own image and seen through to the end, on a phone. That has not happened yet."], &["Local — disk", "Both machines take a disk image, read where it lies; the guest sees it on /dev/vda, and what it writes is kept beside the image, durably.", "Nothing named. A kernel with no block driver cannot use the device, and wisq says so at the end of the run."], &["Local — screen", "The x86-64 machine declares a framebuffer, and a real Alpine kernel finds it: its simpledrm driver initialises on it.", "A view that shows it. The frame is declared, routed, filled by the guest and readable by the host; nothing in the app displays it yet."], &["Local — desktop", "A translator from x86-64 to WebAssembly, with paging, interrupts and a serial port. Under the measurement harness, a real kernel boots into user space.", "A place in the app, which is a decision and the author's. Vector and floating-point instructions. Code the kernel rewrites after it was translated."], &["Agent", "libvirt through virsh, plus a demo backend; TLS by default with a pinned self-signed certificate; a pairing link and its QR code; Bonjour discovery; a VM booted before connecting; a polite ACPI shutdown, then the cord; each VM's memory, read; and `wisq-agent bureau`, from an installation image to a desktop in one command.", "A Proxmox backend, the clear candidate. Writing a remote VM's memory, deliberately not yet."], &["App", "The iPhone app: a configurable touch model, hardware and software keyboards, `.vv` and `.rdp` import, a library that never drops what it cannot read, and local machines whose memory and storage are shown.", "iPad pointer and multi-window, Siri shortcuts and widgets — interface decisions that need the device in hand."], &["Site", "Rust end to end: pages rendered to HTML at build time, two hydrated islands, motion after zamocorp.com that stands down for reduced motion, and offline reading through a service worker.", "Checking the motion in a real iPhone Safari. The screenshots so far are Chromium's."]] },
        Block::H2("Done since the last release"),
        Block::P("The Unreleased section of CHANGELOG.md names two of these, the x86-64 screen and the site. The rest is recorded where the work is recorded as it happens: in the roadmap and the journal."),
        Block::Dl(&[DlItem { term: "Starting from an installation image", detail: "wisq used to refuse an installer image and say what it was. It now reads one — ISO 9660, names as Rock Ridge gives them, the recipes of syslinux, grub and systemd-boot — takes the kernel and initramfs out into the app's storage, attaches the image itself as the disk, and starts the kernel with the image's own command line. The recipe comes from a single menu entry, the first that names a kernel: reading a whole grub.cfg from top to bottom once produced the kernel of one entry and the initramfs of another. And deleting the image takes what was unpacked from it." }, DlItem { term: "A screen for the x86-64 machine", detail: "The kernel learns where to paint from its boot parameters, in XRGB8888 — what simpledrm takes without conversion in the guest, and Core Graphics and Metal on the host — in the address range PCs keep for devices. A revision counter says when the image moved, so that a view does not repaint an identical frame sixty times a second. Unit tests check the bytes; the witness is a real Alpine kernel started under wisq, which initialised simpledrm on that frame. Nobody shows it yet." }, DlItem { term: "Memory sized per architecture", detail: "The ceiling used to be the rv32's addressing limit, applied to every core. Each core now has its own: 2 GiB for rv32, which is where its address space ends, and 16 GiB for the PC machine. The app still leaves 2 GiB to the phone and stays under what iOS says is free at that moment, so the slider offers only what the device can hold." }, DlItem { term: "The desktop, one wall at a time", detail: "Paging behind a translation buffer, page faults and software traps delivered to the guest, the timer raising a real hardware interrupt that wakes a halted guest, a serial port with all its registers — and a hand-written /init whose write reached the serial line, the first time user space spoke through the translator. The app's desktop then gained, one by one, what only the measurement harness had: the boot parameters and command line, a root, a console, and runs that can be bounded and resumed." }, DlItem { term: "The site, in Yew", detail: "Every page, in both languages, is a Yew component rendered to HTML at build time; React and the TypeScript copy of the content are gone. Only the header's settings and the install prompt are hydrated — hydrating whole pages would have put every page's prose into the module each reader downloads — and the motion follows zamocorp.com." }]),
        Block::H2("Done since this page was first written"),
        Block::P("These were on this page as things to come — and one of them as a thing not to do."),
        Block::Dl(&[DlItem { term: "TLS for the agent", detail: "The daemon signs its own certificate and keeps it; the SHA-256 fingerprint travels in the pairing link, and the app pins exactly that certificate, so there is no authority to run. `--no-tls` remains for tunnels that already encrypt." }, DlItem { term: "A real terminal for the local console", detail: "A VT100 cell grid: cursor addressing, erasing, a scrolling region, the alternate screen and deferred line wrap — enough to keep an editor, a pager or top alive." }, DlItem { term: "SPICE", detail: "Complete, and hand-written like the VNC client beside it: display, cursor and input channels on their own connections, sound in both directions, the clipboard through the main channel's agent, and the codecs SPICE invented for itself — LZ, GLZ, QUIC and LZ4 — plus the drawing operations a real desktop leans on." }, DlItem { term: "Persistence for the local machine", detail: "Solved by saving the machine rather than giving it a disk. The whole state below the kernel — RAM, registers, the timer, the bytes queued for the UART — is written out and restored exactly, so the guest comes back mid-syscall if that is where it was." }, DlItem { term: "The x86-64 core", detail: "It runs a stock Alpine kernel and its init — four billion instructions, with no program dying — to the initramfs rescue shell, exactly where QEMU lands on the same images. Ten hardware corpora hold it, and the reference is not a specification read wrong: it is a real processor, asked what it produced." }, DlItem { term: "A virtual disk for the local machine", detail: "This page said it was the wrong plan, and the reasoning was right on the facts and wrong on the conclusion. rv32 nommu kernels do often lack a block driver — but wisq was offering nothing to find: no interrupt controller a device could point at, and a device tree frozen in a blob that could not grow a node. Both are gone. Either machine now takes a disk image, read in place, and the guest sees it on /dev/vda. What it writes goes to a file beside the image before the device answers the guest, so an app killed without notice loses nothing already written, and the image itself never changes. What wisq still cannot do is put the block driver into a kernel you brought: if yours has none, nothing will touch the device — so the device counts its requests, and wisq says so at the end rather than leaving you with a silent disk." }]),
        Block::H2("Next"),
        Block::P("In order. Each item says what it is, why it comes where it does, and what stands in its way."),
        Block::H3("The local desktop, through WebAssembly"),
        Block::P("The work in progress, and the largest of it. iOS gives no App Store app a page of memory that is both writable and executable — no JIT — with one exception: a WKWebView may compile WebAssembly, which is data rather than code. So a translator turns regions of x86-64 instructions into modules WebKit compiles. A faster interpreter would not get there: at the speed the Swift interpreter is measured at, a full desktop takes more than an hour to boot, and a careful rewrite was estimated, then measured, at a few times faster — better, and still not a desktop."),
        Block::P("What is measured, on a real Alpine kernel: every one of the 10 116 entry regions a call reaches translates. That count is now saturated — an unreadable byte stops only its own block, and the refusal waits until execution gets there — so it no longer says whether the decoder is progressing; the same report names, byte by byte, what the translated regions still cannot read. Under JavaScriptCore the translated code runs about an order of magnitude faster than the Rust interpreter on the repository's benchmark. The ratio is what carries: the absolute figures move with the machine, which is why they are not quoted here."),
        Block::P("Paging is in place — a guest address goes through four levels of page tables behind a translation buffer, and the writes to CR0 and CR3 that turn it on are executed rather than refused — and page faults, software traps and the timer's interrupts reach the guest. A probe in the repository, which anyone can re-run, puts a number on what translating costs: on the order of a nanosecond per access while the buffer answers, and more when every access lands on a fresh page. How much more does not hold still — the recorded values differ several-fold from one measurement to another — so that figure is an order of magnitude, not a point."),
        Block::P("How far a kernel gets. Under the measurement harness it goes through its whole boot, and a hand-written /init writes a line that comes out on the serial port, between the kernel starting it and the panic that follows its exit. With Alpine's own initramfs, the machine has reached ring three, where musl's loader runs, and stopped on the first vector instruction it met. Nothing has been displayed: user space is not a desktop."),
        Block::P("In the app, the desktop is built, and a hosted test suite judges it inside a real WebKit: the boot parameters, the frame, an initramfs root, an unreadable root refused, a run resumed, the serial console reaching the app. Nothing in the app's screens opens it yet, and no real Linux kernel has been booted through it under WebKit, anywhere."),
        Block::P("What stands in its way:"),
        Block::Ul(&["Where it goes. The local machine the app runs today is synchronous, keeps a snapshot and takes a disk; the desktop is asynchronous, bounded, and has neither. A screen that hosts both must choose what it loses. Three forms are written down with their costs — a choice of core in the local VM screen, a separate desktop screen, or the desktop in place of the Swift core — and the choice is the author's. Writing it is costly in a specific way: neither SwiftUI nor WebKit exists on a Linux Swift toolchain, so only the iOS job in CI can judge a line of it.", "Vector and floating-point instructions. The Rust cores have neither, and musl's memset begins with one. Adding them means giving sixteen vector registers a form in WebAssembly, redoing the save and restore of the processor state, redoing the snapshot, and bringing the Rust cores before the vector oracles — a direction rather than a slice, and it waits for the author's word.", "Code that changes after it was translated. The host keeps every region it translates for as long as the machine lives, and a Linux kernel rewrites its own text while it boots: the machine does run stale code — that is measured — and the boot survives it for a reason the journal names. The possible fixes are written down; none is chosen yet."]),
        Block::H3("Booting from the image you bring"),
        Block::P("The app now starts an installation image (see above), with the image's own command line. It is read, never invented: a kernel started without its own does not find its root, and the failure lands far from its cause. wisq appends its serial console last, because Linux keeps the last console= it is given, and drops quiet, which would silence the only output there is."),
        Block::P("Why it is still under Next: no distribution has yet been seen booting from its image all the way, on a phone. One real installer image ran for minutes of guest time on an iPhone, then stopped on an instruction the core lacked — named, not frozen — and that instruction has since been written and checked against a real processor. Moving this item takes a boot, not more wiring."),
        Block::H3("RDP"),
        Block::P("The one that matters for Windows guests, and wisq speaks it: negotiation, MCS, key exchange, licensing, capabilities, RLE bitmaps and input, against a real xrdp. What is missing is named rather than half-built, in this order:"),
        Block::Ul(&["NLA/CredSSP. Modern Windows requires it by default, so wisq does not connect to those machines yet. The server everything was written against, xrdp, is not an NLA server, and CredSSP written with nothing to judge it against would be code one only believes good. Until then, a host that demands it is refused by name instead of failing in the middle of a handshake.", "TLS. Asking for it would mean starting it inside a socket that is already open, which wisq's transport cannot do today. Meanwhile the only security wisq speaks does not authenticate the server: its certificate is signed with a key Microsoft made public, so anyone on the path can sit in the middle.", "The virtual channels — the clipboard, sound — the remote cursor, whose pointer messages are read and dropped today, and resizing mid-session.", "RemoteFX and H.264."]),
        Block::P("One question is already settled: RDP decoding does not go through SPICE's surfaces. The two protocols share a shape — rectangles, codecs, a cursor — and none of their meaning; a shared layer, if there is ever one, is the drawing target, not the decoder."),
        Block::H3("More agent backends"),
        Block::P("The agent's backend interface has four methods, and the libvirt backend shows its shape. Proxmox is the clear candidate: its REST API is documented and can be tested here against a fake server, like the rest of the daemon. Plain QEMU is not: QEMU has no daemon, so listing machines means inventing where the list comes from — QMP sockets in a directory, a definitions file — and that is not a decision to take blind. Either way, code written here would never have met a real host: testable, not judgeable."),
        Block::H3("A remote VM's memory, the half that writes"),
        Block::P("The half that reads is done: the agent reads each VM's memory from libvirt and the phone shows it under the VM's name. Writing it is held back on purpose. Measured against a real libvirt: lowering a running guest's memory is a request to its balloon driver, which a guest without one ignores forever — and libvirt says yes anyway. Before there is a slider, the answer has to say what happened rather than what was asked — check afterwards, and say “requested, not yet given” — and name the price: a guest without a balloon driver gives nothing back, and changing the maximum needs a restart."),
        Block::H3("What waits for an Apple machine"),
        Block::P("The roadmap keeps a short list under this heading: things found and understood that cannot be proved from the Linux container where everything else is. The repository's rule is that a change no test can see break is not a change to ship, so these wait rather than go out as unverified fixes."),
        Block::Ul(&["One reader at a time on a network stream. Two concurrent reads would interleave and stitch the stream back together from two positions — gibberish several messages later. It is latent, since no path reads a stream from two tasks today, and the fix needs a probe that parks a read, which only runs where Network.framework does.", "Pinning on the direct machine path, last step. A fingerprint can be pasted in and is enforced; recording it from the connection means seeing the certificate the server presents, and showing it to the person who accepts it — a pin recorded silently on first connection protects against everyone except whoever was there at that moment.", "The port a reconnection never asks for again. The console port is resolved once, before the session; a libvirt domain restarted by someone else can come back on another port, and the reconnection attempts then fail against a machine that is fine. The fix — resolve on every attempt — touches the reconnection loop, the project's flagship promise, so it waits for the time to judge it."]),
        Block::H3("iPad and Siri"),
        Block::P("System cursor, multi-window and indirect pointer on iPad; Siri shortcuts and “connect to…” widgets. Both need the device, and not only to be tested: they are interface decisions one does not take blind. What can be settled from here is settled:"),
        Block::Ul(&["The indirect pointer adds to the touch model rather than replacing it: a system cursor laid over the remote one. Two cursors that diverge are better than one that lies about where the click will land.", "One session per window, never shared: SPICE channels carry per-connection state — image caches, the GLZ window, agent tokens — that cannot be duplicated without lying to the server.", "A shortcut names a saved machine and carries no secret: the token and the fingerprint stay in the Keychain, because an exported shortcut is a file people share without thinking."]),
        Block::H2("What shapes the order"),
        Block::Dl(&[DlItem { term: "No JIT on iOS", detail: "iOS grants executable memory only to development-signed apps. Every local machine is interpreted, or translated to WebAssembly for WebKit to compile; it is not a race for emulation speed, and moving execution to the host remains the main answer." }, DlItem { term: "The network is the budget", detail: "Every decision on the remote side — encodings, pixel format, incremental updates — is judged in bytes per frame and milliseconds of latency, not in CPU cycles." }, DlItem { term: "App Store rule 4.7", detail: "It is the blind spot of competitors built on local emulation: their fate hangs on how Apple reads a rule written for retro-console emulators. The remote half of wisq is a network client, a category as old as the App Store; the local half interprets without a JIT, and the README cites iSH as the precedent." }, DlItem { term: "x86-64 for the local platform", detail: "Decided by the author in September, after the three options and their cost were laid out. RISC-V was not the blocker — Debian, Ubuntu and Fedora have official riscv64 ports. What kept a full distribution from running was a 32-bit machine with no MMU and no disk; x86-64 brings all three at once, and runs what the author wants to run, which ships for x86-64." }]),
        Block::H2("Not planned"),
        Block::Dl(&[DlItem { term: "An Android app", detail: "The portable parts are already portable, but the product is the iPhone app. One platform done properly beats two done badly." }, DlItem { term: "A desktop on the interpreter alone", detail: "Without a JIT, an interpreter makes a console, not a desktop: at the Swift interpreter's measured speed a desktop takes more than an hour to boot, and a rewrite a few times faster is still not a desktop. That is the ceiling wisq is built to avoid rather than to hit: the local desktop goes through WebAssembly, and anything heavier runs on the host." }, DlItem { term: "A core for every architecture", detail: "Not promised, and the roadmap says so. wisq recognises twenty-one architecture families and names a file it cannot run — a Linux kernel for ARM64, in the ARM64 Image format — rather than meeting it with silence. Recognising is not running: an ARM64 or PowerPC core is a lot of work per architecture, not a box to tick." }, DlItem { term: "A kernel patched to run without paging", detail: "It would boot one kernel, not the kernels; wisq is only worth having if the image it runs is the one you brought." }, DlItem { term: "A storage cap that deletes", detail: "The app shows what kernels and saved machines take, and offers a gesture to reclaim the ones whose kernel is gone. The obvious form of a cap is an eviction policy — silently deleting someone's data to stay under a number they did not choose — and it will not be written unless the author asks for it." }, DlItem { term: "A hosted service", detail: "wisq talks to machines you already have. There is no account, no server of ours in the path, and nothing to subscribe to." }]),
        Block::H2("Ruled out by a measurement"),
        Block::P("Each of these was a reasonable idea until a number answered it."),
        Block::Dl(&[DlItem { term: "Metal for the processor core", detail: "Compiling Metal at run time is something Apple allows, so the question stood. The GPU answered no: on one thread, the same loop ran eleven times slower than native Swift on the same machine. A GPU hides the latency of its memory by keeping thousands of threads ready, and an emulated core has one — not a setting, the architecture. Metal stays the right tool for the screen, where pixels are independent." }, DlItem { term: "A custom URL scheme for the kernel image", detail: "The kernel enters the desktop's web view in base64 slices, which was long written down as expensive with no number behind it. Measured on a macOS runner, a kernel of ordinary size crosses in about half a second. A scheme handler would save at most that, for a mechanism no test in the repository can judge." }, DlItem { term: "Faulting to the host on every memory access", detail: "Handing control back to the host costs well over a hundred nanoseconds. Doing it on every memory access would put the machine under a million instructions a second — two orders of magnitude below the Rust interpreter the translator exists to beat." }]),
        Block::Note { tone: Tone::Info, text: "Roadmap items are not promises. If one of these matters to you, an issue saying why is worth more than a vote — it changes the order." },
    ],
};

pub static ROADMAP_FR: Doc = Doc {
    title: "Feuille de route",
    lede: "Où en est chaque partie, la suite dans l'ordre qui compte et ce qui lui barre la route — et ce qui n'est délibérément pas prévu.",
    blocks: &[
        Block::P("Rien ici n'a de date. L'ordre reflète ce qui améliorerait wisq pour quelqu'un qui s'en sert aujourd'hui, pas ce qui serait le plus intéressant à construire."),
        Block::P("Cette page résume docs/ROADMAP.md, le registre de travail du projet. Ce fichier s'écrit en français au fil du travail, une tranche à la fois, et chaque tranche dit ce qu'elle a mesuré, ce qu'elle a cassé exprès pour voir si un test s'en apercevait, et ce qu'elle ne montre pas. CHANGELOG.md dit ce que chaque version a porté ; docs/JOURNAL.md, à côté de la feuille de route, consigne les séances et ce qui y a été décidé. Les détails, les dates et la commande derrière chaque chiffre vivent là-bas."),
        Block::H2("Où en est chaque partie"),
        Block::P("Une ligne par domaine, dans les mots de la feuille de route et du tableau d'état du README : ce qui est fait, et la première chose nommée ensuite — ou rien, quand rien ne l'est."),
        Block::Table { columns: &["Domaine", "Fait", "Ensuite"], rows: &[&["Distant — VNC", "Un client RFB 3.8 : les encodages classiques, puis zlib, ZRLE et Tight avec JPEG, sur des flux de compression qui vivent autant que la session ; les mises à jour continues, le curseur du serveur dessiné sur place, le redimensionnement du bureau, le presse-papiers, et la reconnexion à repli exponentiel qui ne réessaie jamais un mot de passe refusé.", "Rien de nommé pour VNC lui-même. Trois choses qui concernent les connexions distantes en général sont rangées dans la liste de la feuille de route de ce qui attend une machine Apple — voir plus bas."], &["Distant — SPICE", "Complet : chaque canal sur sa propre connexion, les codecs que SPICE s'est inventés, le son dans les deux sens, le presse-papiers, les flux vidéo, les trois caches, les fichiers `.vv`, et un fichier envoyé du téléphone vers l'invité.", "Rien de nommé. Les codecs vidéo qu'un serveur pourrait choisir ne sont pas annoncés, exprès : wisq ne les décode pas."], &["Distant — RDP", "Négociation, MCS, échange de clés, licence, capacités, bitmaps RLE et entrées, mesurés contre un vrai xrdp avec FreeRDP pour oracle des pixels ; les fichiers `.rdp` sont lus.", "NLA/CredSSP d'abord, parce que les Windows modernes l'exigent par défaut ; puis TLS, les canaux virtuels, le curseur, la retaille en cours de session, RemoteFX et H.264."], &["Local — RISC-V", "rv32ima écrit deux fois, en Rust et en Swift, et comparé instruction par instruction en CI — c'est le Rust qui est embarqué. Un vrai noyau jusqu'au shell, un terminal qui fait vivre un éditeur, la suspension par instantané, un disque, une mémoire qu'on règle.", "Rien de prévu. Les distributions complètes sont passées à la machine x86-64 quand la plate-forme locale a changé."], &["Local — x86-64", "Un noyau Alpine standard jusqu'au shell de secours de l'initramfs, là où QEMU arrive sur les mêmes images. Un disque, un instantané, jusqu'à 16 Gio de mémoire dans la limite de ce que le téléphone permet, et les images d'installation démarrées depuis ce qu'elles contiennent.", "Une distribution démarrée depuis sa propre image et vue jusqu'au bout, sur un téléphone. Ce n'est pas encore arrivé."], &["Local — disque", "Les deux machines prennent une image de disque, lue là où elle est ; l'invité la voit sur /dev/vda, et ce qu'il y écrit est gardé à côté de l'image, durablement.", "Rien de nommé. Un noyau sans pilote bloc ne peut pas se servir du périphérique, et wisq le dit à la fin de l'exécution."], &["Local — écran", "La machine x86-64 déclare un tampon d'image, et un vrai noyau Alpine le trouve : son pilote simpledrm s'y initialise.", "Une vue qui le montre. Le cadre est déclaré, routé, rempli par l'invité et lisible par l'hôte ; rien dans l'application ne l'affiche encore."], &["Local — bureau", "Un traducteur de x86-64 vers WebAssembly, avec pagination, interruptions et port série. Sous le montage de mesure, un vrai noyau démarre jusqu'à l'espace utilisateur.", "Une place dans l'application, qui est une décision et revient à l'auteur. Les instructions vectorielles et la virgule flottante. Le code que le noyau réécrit après sa traduction."], &["Agent", "libvirt via virsh, plus un backend de démonstration ; TLS par défaut avec un certificat auto-signé épinglé ; un lien d'appairage et son QR ; la découverte Bonjour ; la VM démarrée avant la connexion ; l'arrêt ACPI poli, puis le cordon ; la mémoire de chaque VM, lue ; et `wisq-agent bureau`, d'une image d'installation à un bureau en une commande.", "Un backend Proxmox, le candidat net. Écrire la mémoire d'une VM distante, délibérément pas encore."], &["Application", "L'application iPhone : un modèle tactile réglable, claviers matériel et logiciel, l'import `.vv` et `.rdp`, une bibliothèque qui ne jette jamais ce qu'elle ne sait pas lire, et des machines locales dont la mémoire et le stockage sont affichés.", "Le pointeur et le multi-fenêtres sur iPad, les raccourcis Siri et les widgets — des décisions d'interface qui demandent l'appareil en main."], &["Site", "Rust de bout en bout : pages rendues en HTML à la construction, deux îlots hydratés, un mouvement d'après zamocorp.com qui s'efface pour qui demande moins d'animation, et une lecture hors ligne par un service worker.", "Vérifier le mouvement dans un vrai Safari d'iPhone. Les captures faites jusqu'ici sont celles de Chromium."]] },
        Block::H2("Fait depuis la dernière version"),
        Block::P("La section Unreleased de CHANGELOG.md en nomme deux, l'écran de la machine x86-64 et le site. Le reste est consigné là où le travail se consigne à mesure qu'il se fait : dans la feuille de route et le journal."),
        Block::Dl(&[DlItem { term: "Démarrer depuis une image d'installation", detail: "wisq refusait une image d'installation en disant ce qu'elle était. Il la lit maintenant — ISO 9660, les noms rendus par Rock Ridge, les recettes de syslinux, de grub et de systemd-boot —, sort le noyau et l'initramfs dans le stockage de l'application, branche l'image elle-même comme disque, et démarre le noyau avec la ligne de commande de l'image. La recette vient d'une seule entrée de menu, la première qui nomme un noyau : lire un grub.cfg d'un bout à l'autre a un jour rendu le noyau d'une entrée et l'initramfs d'une autre. Et supprimer l'image emporte ce qui en avait été déballé." }, DlItem { term: "Un écran pour la machine x86-64", detail: "Le noyau apprend où peindre par ses paramètres de démarrage, en XRGB8888 — ce que simpledrm prend sans conversion côté invité, et Core Graphics et Metal côté hôte —, dans la plage d'adresses que les PC réservent aux périphériques. Un compteur de révision dit quand l'image a bougé, pour qu'une vue ne repeigne pas soixante fois par seconde une image identique. Les tests unitaires vérifient les octets ; le témoin est un vrai noyau Alpine démarré sous wisq, qui a initialisé simpledrm sur ce cadre. Personne ne le montre encore." }, DlItem { term: "La mémoire, réglée par architecture", detail: "Le plafond était la limite d'adressage du rv32, appliquée à tous les cœurs. Chaque cœur a maintenant le sien : 2 Gio pour le rv32, là où finit son espace d'adressage, et 16 Gio pour la machine PC. L'application laisse toujours 2 Gio au téléphone et reste sous ce qu'iOS dit libre à cet instant, si bien que le curseur n'offre que ce que l'appareil peut tenir." }, DlItem { term: "Le bureau, un mur après l'autre", detail: "La pagination derrière un tampon de traduction, les fautes de page et les pièges logiciels délivrés à l'invité, le timer qui lève une vraie interruption matérielle et réveille un invité endormi, un port série avec tous ses registres — et un /init écrit à la main dont l'écriture est arrivée sur la ligne série : la première fois que l'espace utilisateur parlait à travers le traducteur. Le bureau de l'application a ensuite reçu, une à une, les pièces que seul le montage de mesure avait : les paramètres de démarrage et la ligne de commande, une racine, une console, et des exécutions qu'on peut borner et reprendre." }, DlItem { term: "Le site, en Yew", detail: "Chaque page, dans les deux langues, est un composant Yew rendu en HTML à la construction ; React et la copie TypeScript du contenu sont partis. Seuls les réglages de l'en-tête et l'invite d'installation sont hydratés — hydrater les pages entières aurait mis la prose de chacune dans le module que chaque lecteur télécharge —, et le mouvement suit zamocorp.com." }]),
        Block::H2("Fait depuis la première écriture de cette page"),
        Block::P("Ces points figuraient ici comme des choses à venir — et l'un d'eux comme une chose à ne pas faire."),
        Block::Dl(&[DlItem { term: "Le TLS de l'agent", detail: "Le démon signe son propre certificat et le garde ; l'empreinte SHA-256 voyage dans le lien d'appairage, et l'application épingle exactement ce certificat — pas d'autorité à faire tourner. `--no-tls` reste pour les tunnels qui chiffrent déjà." }, DlItem { term: "Un vrai terminal pour la console locale", detail: "Une grille de cellules VT100 : adressage du curseur, effacements, région de défilement, écran alterné et retour à la ligne différé — de quoi faire vivre un éditeur, un pager ou top." }, DlItem { term: "SPICE", detail: "Complet, et écrit à la main comme le client VNC d'à côté : canaux affichage, curseur et entrées sur leurs propres connexions, le son dans les deux sens, le presse-papiers par l'agent du canal principal, et les codecs que SPICE s'est inventés — LZ, GLZ, QUIC et LZ4 — plus les opérations de dessin sur lesquelles un vrai bureau s'appuie." }, DlItem { term: "La persistance de la machine locale", detail: "Résolue en sauvant la machine plutôt qu'en lui donnant un disque. Tout l'état sous le noyau — la RAM, les registres, le timer, les octets en attente sur l'UART — est écrit puis restauré à l'identique, si bien que l'invité revient au milieu d'un appel système si c'est là qu'il était." }, DlItem { term: "Le cœur x86-64", detail: "Il fait tourner un noyau Alpine standard et son init — quatre milliards d'instructions, sans qu'un programme meure — jusqu'au shell de secours de l'initramfs, exactement là où QEMU arrive sur les mêmes images. Dix corpus matériels le tiennent, et la référence n'est pas une spécification lue de travers : c'est un vrai processeur, à qui l'on demande ce qu'il a produit." }, DlItem { term: "Un disque virtuel pour la machine locale", detail: "Cette page disait que c'était le mauvais plan, et le raisonnement était juste sur les faits et faux sur la conclusion. Les noyaux rv32 nommu manquent souvent de pilote bloc — mais wisq n'offrait rien à trouver : aucun contrôleur d'interruption qu'un périphérique puisse désigner, et un arbre de périphériques figé dans un blob où aucun nœud ne pouvait pousser. Les deux ont disparu. Les deux machines prennent maintenant une image de disque, lue sur place, et l'invité la voit sur /dev/vda. Ce qu'il y écrit part dans un fichier à côté de l'image avant que le périphérique ne lui réponde, si bien qu'une application tuée sans préavis ne perd rien de ce qui était écrit, et l'image elle-même ne change jamais. Ce que wisq ne peut toujours pas faire, c'est mettre le pilote bloc dans un noyau que vous apportez : si le vôtre n'en a pas, personne ne touchera le périphérique — alors le périphérique compte ses requêtes, et wisq le dit à la fin plutôt que de vous laisser devant un disque muet." }]),
        Block::H2("Ensuite"),
        Block::P("Dans l'ordre. Chaque point dit ce qu'il est, pourquoi il vient là, et ce qui lui barre la route."),
        Block::H3("Le bureau local, par WebAssembly"),
        Block::P("Le travail en cours, et le plus gros. iOS n'accorde à aucune application de l'App Store une page de mémoire à la fois inscriptible et exécutable — pas de JIT —, avec une exception : un WKWebView peut compiler du WebAssembly, qui est une donnée et non du code. Un traducteur transforme donc des régions d'instructions x86-64 en modules que WebKit compile. Un interpréteur plus rapide n'y arriverait pas : à la vitesse mesurée de l'interpréteur Swift, un bureau complet demande plus d'une heure pour démarrer, et une réécriture soignée, estimée puis mesurée, va quelques fois plus vite — mieux, et toujours pas un bureau."),
        Block::P("Ce qui est mesuré, sur un vrai noyau Alpine : les 10 116 régions d'entrée qu'un `call` atteint se traduisent toutes. Ce compte est désormais saturé — un octet illisible n'arrête plus que son propre bloc, et le refus attend que l'exécution y arrive —, donc il ne dit plus si le décodeur progresse ; le même relevé nomme, octet par octet, ce que les régions traduites ne savent pas encore lire. Sous JavaScriptCore, le code traduit va environ un ordre de grandeur plus vite que l'interpréteur Rust sur le banc du dépôt. C'est le rapport qui se transporte : les valeurs absolues bougent avec la machine, et c'est pourquoi elles ne sont pas citées ici."),
        Block::P("La pagination est là — une adresse invitée traverse quatre niveaux de tables derrière un tampon de traduction, et les écritures de CR0 et CR3 qui l'allument sont exécutées plutôt que refusées — et les fautes de page, les pièges logiciels et les interruptions du timer parviennent à l'invité. Une sonde, dans le dépôt et relançable, chiffre ce que coûte la traduction : de l'ordre d'une nanoseconde par accès tant que le tampon répond, et davantage quand chaque accès tombe sur une page neuve. Combien davantage ne tient pas en place — les valeurs relevées varient de plusieurs fois d'une mesure à l'autre —, et ce chiffre-là est donc un ordre de grandeur, pas un point."),
        Block::P("Jusqu'où va un noyau. Sous le montage de mesure, il traverse tout son démarrage, et un /init écrit à la main imprime une ligne qui sort sur le port série, entre le moment où le noyau le lance et la panique qui suit sa sortie. Avec l'initramfs d'Alpine lui-même, la machine est allée jusqu'en anneau trois, où tourne le chargeur de musl, et s'est arrêtée sur la première instruction vectorielle rencontrée. Rien n'a été affiché : l'espace utilisateur n'est pas un bureau."),
        Block::P("Dans l'application, le bureau est construit, et une suite de tests hébergés le juge dans un vrai WebKit : les paramètres de démarrage, le cadre, une racine initramfs, une racine illisible refusée, une exécution reprise, la console série qui arrive jusqu'à l'application. Rien dans les écrans de l'application ne l'ouvre encore, et aucun vrai noyau Linux n'a été démarré par lui sous WebKit, nulle part."),
        Block::P("Ce qui lui barre la route :"),
        Block::Ul(&["Sa place. La machine locale que l'application fait tourner aujourd'hui est synchrone, garde un instantané et prend un disque ; le bureau est asynchrone, borné, et n'a ni l'un ni l'autre. Un écran qui héberge les deux doit choisir ce qu'il perd. Trois formes sont écrites avec leurs coûts — un choix de cœur dans l'écran VM locale, un écran « Bureau » à part, ou le bureau à la place du cœur Swift — et le choix revient à l'auteur. L'écrire coûte d'une façon précise : ni SwiftUI ni WebKit n'existent sur une chaîne Swift Linux, donc seul le job iOS de la CI peut juger une ligne de ce branchement.", "Les instructions vectorielles et la virgule flottante. Les cœurs Rust n'ont ni l'une ni l'autre, et le memset de musl commence par l'une d'elles. Les ajouter, c'est donner une forme en WebAssembly à seize registres vectoriels, refaire la sauvegarde et la restauration de l'état du processeur, refaire l'instantané, et faire comparaître les cœurs Rust devant les oracles vectoriels — une direction plutôt qu'une tranche, et elle attend la parole de l'auteur.", "Le code qui change après sa traduction. L'hôte garde chaque région traduite aussi longtemps que la machine vit, et un noyau Linux réécrit son propre texte pendant qu'il démarre : la machine exécute bel et bien du code périmé — c'est mesuré — et le démarrage y survit pour une raison que le journal nomme. Les corrections possibles sont écrites ; aucune n'est encore choisie."]),
        Block::H3("Démarrer depuis l'image que vous apportez"),
        Block::P("L'application démarre maintenant une image d'installation (voir plus haut), avec la ligne de commande de l'image elle-même. Elle se lit et ne s'invente pas : un noyau démarré sans la sienne ne trouve pas sa racine, et la panne tombe loin de sa cause. wisq y ajoute sa console série en dernier, parce que Linux retient le dernier console= qu'on lui donne, et retire quiet, qui éteindrait la seule sortie qui existe."),
        Block::P("Pourquoi c'est encore dans « Ensuite » : aucune distribution n'a encore été vue démarrer depuis son image jusqu'au bout, sur un téléphone. Une vraie image d'installation a tourné plusieurs minutes de temps invité sur un iPhone, puis s'est arrêtée sur une instruction qui manquait au cœur — nommée, pas figée —, et cette instruction a depuis été écrite et confrontée à un vrai processeur. Faire bouger ce point demande un démarrage, pas davantage de branchement."),
        Block::H3("RDP"),
        Block::P("Celui qui compte pour les invités Windows, et wisq le parle : négociation, MCS, échange de clés, licence, capacités, bitmaps RLE et entrées, contre un vrai xrdp. Ce qui manque est nommé plutôt qu'à moitié fait, dans cet ordre :"),
        Block::Ul(&["NLA/CredSSP. Les Windows modernes l'exigent par défaut, donc wisq ne s'y connecte pas encore. Le serveur contre lequel tout a été écrit, xrdp, n'est pas un serveur NLA, et un CredSSP écrit sans rien contre quoi le juger serait du code qu'on croit bon. D'ici là, un hôte qui l'exige est refusé par son nom au lieu d'échouer au milieu d'une poignée de main.", "TLS. Le demander supposerait de le démarrer dans une socket déjà ouverte, ce que le transport de wisq ne sait pas faire aujourd'hui. En attendant, la seule sécurité que wisq parle n'authentifie pas le serveur : son certificat est signé par une clé que Microsoft a rendue publique, donc n'importe qui sur le chemin peut se mettre au milieu.", "Les canaux virtuels — le presse-papiers, le son —, le curseur distant, dont les messages de pointeur sont aujourd'hui lus et jetés, et la retaille en cours de session.", "RemoteFX et H.264."]),
        Block::P("Une question est déjà tranchée : le décodage RDP ne repasse pas par les surfaces de SPICE. Les deux protocoles partagent la forme — des rectangles, des codecs, un curseur — et rien de leur sens ; la couche commune, si elle existe un jour, est la cible de dessin, pas le décodeur."),
        Block::H3("D'autres backends d'agent"),
        Block::P("L'interface des backends de l'agent a quatre méthodes, et le backend libvirt en montre la forme. Proxmox est le candidat net : son API REST est documentée et se teste ici contre un faux serveur, comme le reste du démon. QEMU nu ne l'est pas : QEMU n'a pas de démon, donc énumérer les machines demande d'inventer d'où vient la liste — des sockets QMP dans un répertoire, un fichier de définitions —, et ce n'est pas une décision à prendre au jugé. Dans les deux cas, le code écrit ici n'aurait jamais rencontré un vrai hôte : testable, pas jugeable."),
        Block::H3("La mémoire d'une VM distante, la moitié qui écrit"),
        Block::P("La moitié qui lit est faite : l'agent lit la mémoire de chaque VM dans libvirt, et le téléphone l'affiche sous le nom de la VM. Écrire est retenu exprès. Mesuré contre un vrai libvirt : baisser la mémoire d'un invité qui tourne est une demande à son pilote balloon, qu'un invité sans ce pilote ignore pour toujours — et libvirt répond oui quand même. Avant qu'il y ait un curseur, la réponse doit dire ce qui s'est passé et non ce qui a été demandé — vérifier après coup, et rendre « demandé, pas encore rendu » — et nommer le prix : un invité sans pilote balloon ne rend rien, et changer le maximum demande un redémarrage."),
        Block::H3("Ce qui attend une machine Apple"),
        Block::P("La feuille de route tient sous ce titre une liste courte : ce qui est trouvé et compris mais ne peut pas être prouvé depuis le conteneur Linux où le reste l'est. La règle du dépôt est qu'une modification qu'aucun test ne peut voir casser n'est pas une modification livrable : ces points attendent plutôt que de partir en correctifs non vérifiés."),
        Block::Ul(&["Une lecture à la fois sur un flux réseau. Deux lectures concurrentes s'entrelaceraient et recoudraient le flux depuis deux positions — du charabia plusieurs messages plus loin. C'est latent, puisque aucun chemin ne lit un flux depuis deux tâches aujourd'hui, et le correctif demande une sonde qui gare une lecture, qui ne tourne que là où Network.framework existe.", "L'épinglage du chemin machine, dernière étape. Une empreinte se colle et s'applique ; l'enregistrer depuis la connexion demande de voir le certificat que le serveur présente, et de le montrer à la personne qui l'accepte — un épinglage enregistré en silence à la première connexion protège de tout le monde sauf de qui était là à ce moment-là.", "Le port qu'une reconnexion ne redemande jamais. Le port de console est résolu une fois, avant la session ; un domaine libvirt redémarré par quelqu'un d'autre peut revenir sur un autre port, et les tentatives de reconnexion échouent alors contre une machine qui va bien. Le correctif — résoudre à chaque tentative — touche la boucle de reconnexion, la promesse phare du projet : il attend le temps de le juger."]),
        Block::H3("iPad et Siri"),
        Block::P("Le curseur système, le multi-fenêtres et le pointeur indirect sur iPad ; les raccourcis Siri et les widgets « se connecter à … ». Les deux demandent l'appareil, et pas seulement pour être testés : ce sont des décisions d'interface qu'on ne prend pas au jugé. Ce qui peut être tranché d'ici l'est :"),
        Block::Ul(&["Le pointeur indirect s'ajoute au modèle tactile au lieu de le remplacer : un curseur système posé par-dessus le curseur distant. Deux curseurs qui divergent valent mieux qu'un seul qui ment sur l'endroit où le clic atterrira.", "Une session par fenêtre, jamais partagée : les canaux SPICE portent un état par connexion — caches d'images, fenêtre GLZ, jetons de l'agent — qu'on ne peut pas dédoubler sans mentir au serveur.", "Un raccourci nomme une machine enregistrée et ne transporte aucun secret : le jeton et l'empreinte restent dans le trousseau, parce qu'un raccourci exporté est un fichier qu'on partage sans y penser."]),
        Block::H2("Ce qui donne l'ordre"),
        Block::Dl(&[DlItem { term: "Pas de JIT sur iOS", detail: "iOS n'accorde de mémoire exécutable qu'aux applications signées pour le développement. Toute machine locale est interprétée, ou traduite en WebAssembly pour que WebKit la compile ; ce n'est pas une course à la vitesse d'émulation, et déporter l'exécution vers l'hôte reste la réponse principale." }, DlItem { term: "Le réseau est le budget", detail: "Chaque décision du côté distant — encodages, format de pixel, mises à jour incrémentales — se juge en octets par image et en millisecondes de latence, pas en cycles processeur." }, DlItem { term: "La règle 4.7 de l'App Store", detail: "C'est l'angle mort des concurrents fondés sur l'émulation locale : leur sort dépend de la lecture qu'Apple fait d'une règle écrite pour les émulateurs de consoles rétro. La moitié distante de wisq est un client réseau, une catégorie aussi ancienne que l'App Store ; la moitié locale interprète sans JIT, et le README cite iSH comme précédent." }, DlItem { term: "x86-64 pour la plate-forme locale", detail: "Décidé par l'auteur en septembre, après avoir vu les trois options et leur coût. RISC-V n'était pas le blocage — Debian, Ubuntu et Fedora ont des ports riscv64 officiels. Ce qui empêchait une distribution complète de tourner, c'était une machine en 32 bits, sans MMU et sans disque ; x86-64 apporte les trois d'un coup, et fait tourner ce que l'auteur veut faire tourner, qui est distribué en x86-64." }]),
        Block::H2("Non prévu"),
        Block::Dl(&[DlItem { term: "Une application Android", detail: "Les parties portables le sont déjà, mais le produit est l'application iPhone. Une plateforme faite correctement vaut mieux que deux faites mal." }, DlItem { term: "Un bureau sur l'interpréteur seul", detail: "Sans JIT, un interpréteur fait une console, pas un bureau : à la vitesse mesurée de l'interpréteur Swift, un bureau demande plus d'une heure pour démarrer, et une réécriture quelques fois plus rapide n'en fait toujours pas un. C'est le plafond que wisq est construit pour éviter, pas pour l'atteindre : le bureau local passe par WebAssembly, et ce qui est plus lourd tourne sur l'hôte." }, DlItem { term: "Un cœur pour chaque architecture", detail: "Pas promis, et la feuille de route le dit. wisq reconnaît vingt et une familles d'architectures et nomme un fichier qu'il ne sait pas exécuter — « un noyau Linux pour ARM64, au format Image ARM64 » plutôt que le silence. Reconnaître n'est pas exécuter : un cœur ARM64 ou PowerPC est un lot par architecture, pas une case à cocher." }, DlItem { term: "Un noyau modifié pour tourner sans pagination", detail: "Ce serait faire démarrer un noyau, pas les noyaux ; wisq n'a d'intérêt que si l'image qu'il fait tourner est celle que vous avez apportée." }, DlItem { term: "Un plafond de stockage qui supprime", detail: "L'application montre ce que noyaux et machines sauvegardées occupent, et offre un geste pour reprendre celles dont le noyau n'existe plus. La forme évidente d'un plafond est une politique d'éviction — supprimer en silence les données de quelqu'un pour rester sous un nombre qu'il n'a pas choisi —, et elle ne sera pas écrite sans que l'auteur la demande." }, DlItem { term: "Un service hébergé", detail: "wisq parle à des machines que vous avez déjà. Pas de compte, aucun serveur à nous sur le chemin, et rien à quoi s'abonner." }]),
        Block::H2("Écarté par une mesure"),
        Block::P("Chacune de ces idées tenait debout jusqu'à ce qu'un nombre y réponde."),
        Block::Dl(&[DlItem { term: "Metal pour le cœur du processeur", detail: "Compiler du Metal à l'exécution est une chose qu'Apple autorise, donc la question tenait debout. Le GPU a répondu non : sur un fil, la même boucle tournait onze fois plus lentement qu'en Swift natif sur la même machine. Un GPU cache la latence de sa mémoire en tenant des milliers de fils prêts, et un cœur émulé n'en a qu'un — ce n'est pas un réglage, c'est l'architecture. Metal reste le bon outil pour l'écran, où les pixels sont indépendants." }, DlItem { term: "Un schéma d'URL à nous pour l'image du noyau", detail: "Le noyau entre dans la vue web du bureau par tranches de base64, ce qui a longtemps été écrit « cher » sans qu'aucun nombre soit derrière. Mesuré sur un coureur macOS, un noyau de taille ordinaire traverse en une demi-seconde environ. Un gestionnaire de schéma gagnerait au mieux cela, pour un mécanisme qu'aucun test du dépôt ne peut juger." }, DlItem { term: "Fauter vers l'hôte à chaque accès mémoire", detail: "Rendre la main à l'hôte coûte bien plus de cent nanosecondes. Le faire à chaque accès mémoire ramènerait la machine sous le million d'instructions par seconde — deux ordres de grandeur sous l'interpréteur Rust que le traducteur existe pour dépasser." }]),
        Block::Note { tone: Tone::Info, text: "Les points de cette feuille de route ne sont pas des promesses. Si l'un d'eux vous importe, une issue expliquant pourquoi vaut mieux qu'un vote — elle change l'ordre." },
    ],
};
